<?php
require_once '../config/app.php'; require_once '../includes/security.php'; require_once '../includes/notifications.php'; start_secure_session();require_permission('jobs.view');$pdo=db();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';
 else try{
  if(($_POST['action']??'')==='add'){
   $pdo->beginTransaction();$uid='JOB-'.strtoupper(bin2hex(random_bytes(4)));
   $st=$pdo->prepare("INSERT INTO jobs(job_uid,organization,department,job_title,short_description,job_type,location,state,district,vacancy_count,status,source_url,application_url,closing_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
   $st->execute([$uid,trim($_POST['organization']),trim($_POST['department']),trim($_POST['job_title']),trim($_POST['short_description']),trim($_POST['job_type']),trim($_POST['location']),trim($_POST['state']),trim($_POST['district']),(int)($_POST['vacancy_count']??0),'pending_verification',trim($_POST['source_url']),trim($_POST['application_url']),$_POST['closing_date']?:null,$_SESSION['admin_id']]);$jid=$pdo->lastInsertId();
   $st=$pdo->prepare("INSERT INTO job_eligibility(job_id,min_age,max_age,education_required,experience_required,gender_requirement,nationality_requirement,domicile_requirement,category_rules,pwd_rules,other_conditions,age_relaxation_rules,allowed_categories,pwd_min_percentage,pwd_eligibility,ex_serviceman_rule,domicile_states,qualification_rules,minimum_experience_months,experience_notes,eligibility_review_notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
   $st->execute([$jid,$_POST['min_age']!==''?(int)$_POST['min_age']:null,$_POST['max_age']!==''?(int)$_POST['max_age']:null,trim($_POST['education_required']),trim($_POST['experience_required']),trim($_POST['gender_requirement']),trim($_POST['nationality_requirement']?:'Indian'),trim($_POST['domicile_requirement']),trim($_POST['category_rules']),trim($_POST['pwd_rules']),trim($_POST['other_conditions']),trim($_POST['age_relaxation_rules']),trim($_POST['allowed_categories']),$_POST['pwd_min_percentage']!==''?(float)$_POST['pwd_min_percentage']:null,trim($_POST['pwd_eligibility']),trim($_POST['ex_serviceman_rule']),trim($_POST['domicile_states']),trim($_POST['qualification_rules']),$_POST['minimum_experience_months']!==''?(int)$_POST['minimum_experience_months']:null,trim($_POST['experience_notes']),trim($_POST['eligibility_review_notes'])]);
   $st=$pdo->prepare("INSERT INTO job_dates(job_id,notification_date,application_start,application_end,fee_last_date,exam_date,admit_card_date,result_date) VALUES(?,?,?,?,?,?,?,?)");
   $st->execute([$jid,$_POST['notification_date']?:null,$_POST['application_start']?:null,$_POST['application_end']?:null,$_POST['fee_last_date']?:null,$_POST['exam_date']?:null,$_POST['admit_card_date']?:null,$_POST['result_date']?:null]);
   $pdo->prepare("INSERT INTO audit_logs(admin_id,action,module,record_id,new_value,created_at) VALUES(?,?,?,?,?,NOW())")->execute([$_SESSION['admin_id'],'CREATE','jobs',$jid,'pending_verification']);$pdo->commit();
   flash('success','Job saved as Pending Verification.');redirect('jobs.php');
  }
  if(($_POST['action']??'')==='status'){
   if(($_POST['status']??'')==='published') require_permission('jobs.publish');
   elseif(in_array(($_POST['status']??''),['expired','archived'])) require_permission('jobs.verify');
   $id=(int)$_POST['id'];$status=$_POST['status'];if(!in_array($status,['draft','pending_verification','published','expired','archived']))throw new Exception();
   $pdo->prepare("UPDATE jobs SET status=?,published_at=CASE WHEN ?='published' THEN NOW() ELSE published_at END,verified_by=CASE WHEN ?='published' THEN ? ELSE verified_by END WHERE id=?")->execute([$status,$status,$status,$_SESSION['admin_id'],$id]);
   $pdo->prepare("INSERT INTO audit_logs(admin_id,action,module,record_id,new_value,created_at) VALUES(?,?,?,?,?,NOW())")->execute([$_SESSION['admin_id'],'STATUS','jobs',$id,$status]); if($status==='published'){ try{ $count=notify_published_job_matches($pdo,$id,(int)$_SESSION['admin_id']); flash('success','Job published. '.$count.' matching candidate notification(s) created.'); }catch(Throwable $notifyError){ flash('success','Job published. Notification generation could not complete; review the notification queue.'); } } else { flash('success','Job status updated.'); } redirect('jobs.php');
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not save job.';}
}
$rows=$pdo->query("SELECT j.*,e.min_age,e.max_age,e.education_required FROM jobs j LEFT JOIN job_eligibility e ON e.job_id=j.id ORDER BY j.created_at DESC")->fetchAll();
$page_title='Government Jobs';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?>
